#!/bin/bash
# stack-import-fixture-stage: root's targeted job for r12's one stack-only failure (PREPARED; NOT run by Claude). No build: the
# candidate's committed (regenerated) admission bundle is used as archived, its bytes pinned. Nothing in r12 is written.
#   ST=/home/steven/Documents/Codex/2026-10-18/wo/work/rpc-production-final-20261025/stack-import-fixture-stage
#   python3 -u /home/steven/Documents/Codex/2026-10-18/wo/work/claude-test-queue.py --mib 256 --log $ST/logs/root-stack-import-fixture.guard -- unshare -rn bash $ST/jobs/root-stack-import-fixture.sh > $ST/logs/root-stack-import-fixture.out 2>&1; echo $? > $ST/logs/root-stack-import-fixture.rc
# PASS only if: ORIGINAL test = rc 1, 3 tests, 2 pass, 1 fail (exactly test 1, "importers still name chainVerifierFromEnv");
# PATCHED test = rc 0, 3 tests, 3 pass; both with 0 skipped/todo/cancelled.
set -uo pipefail
ip link set lo up 2>/dev/null || true
P=/home/steven/Documents/Codex/2026-10-18/wo/work/rpc-production-final-20261025
ST=$P/stack-import-fixture-stage; R12=$P/rpc-runtime-composition-stage/r12; FG=$R12/run/r4-20261026T031250Z/trees/final/.git
E=/home/steven/Documents/Codex/2026-10-18/wo/work/enclave; C=debbfb377d90f4193ea9182f5cb67d714ffaa322; TF=test/stack-windows-chain-reader.test.mjs
OUT=$ST/runs/$(date -u +%Y%m%dT%H%M%SZ)-$$; rc=0; export GIT_OPTIONAL_LOCKS=0
die() { echo "## INVALID: $*"; echo "## stack-import rc=1"; exit 1; }
[ ! -e "$OUT" ] && mkdir -p "$OUT/logs" || die "output dir"
ip -o route 2>/dev/null | grep -q . && die "network route present: run under unshare -rn"
(cd "$ST" && sha256sum -c --quiet SHA256SUMS) || die "stage files differ from SHA256SUMS"
(cd "$R12" && sha256sum -c --quiet SHA256SUMS) || die "r12 stage changed"
[ "$(sha256sum < $R12/tools/deps-identity.py | cut -c1-64)" = f54c59356e798d5cdb2be7d7642e30e63ae668015c0ee39bccffc254c7b22484 ] || die "deps-identity.py differs"
while read -r b p; do [ "$(git --no-optional-locks --git-dir=$FG rev-parse $C:$p)" = $b ] || die "candidate blob of $p is not $b"; done <<'EOF'
06b6fa9ab9e15237aca6355cdf5e69a877b0152e windows/node/chain-reader.mjs
3d0311e462002783556a0abc984cf51b170a5b01 windows/node/chain.mjs
05a053d668b75965a4f14b0fb2967092bf67368d windows/node/chain-selection.mjs
6665ee5ebf33df04886173f1e19412274ac8f902 windows/node/host-admission.bundle.mjs
ccbf1fb1f17536442390ed5f5b2125291fffbca9 network/host-admission-node.mjs
EOF
[ "$(sha256sum < $R12/stack-tests/stack-windows-chain-reader.test.mjs | cut -c1-64)" = 376972696cc15c3b85257fb02feb9beffb4865b6b3c72c207f17d31f33b97640 ] || die "r12 stack test differs"
[ "$(sha256sum < $R12/stack-tests/helpers-recorder.mjs | cut -c1-64)" = 6ee801d41af116edfbaf862fe6757eb02b2d26f052b70f8d66740e9c00fe7613 ] || die "r12 recorder helper differs"
mk() { local T=$OUT/$1; mkdir -p $T && git --no-optional-locks --git-dir=$FG archive $C | tar -x -C $T || die "$1 export"
  [ "$(sha256sum < $T/windows/node/host-admission.bundle.mjs | cut -c1-64)" = dd99e9e2bf61dd38c0631fd32bc7d000e256cd79c78abf92fcf0a8a6804b40ee ] || die "$1: admission bundle is not the r12 regenerated bytes"
  cp $R12/stack-tests/stack-windows-chain-reader.test.mjs $R12/stack-tests/helpers-recorder.mjs $T/test/ || die "$1 stack test copy"
  for d in . network relay; do src=$E/node_modules; [ $d != . ] && src=$E/$d/node_modules; dst=$T/node_modules; [ $d != . ] && dst=$T/$d/node_modules
    ln -s "$(realpath -e $src)" $dst || die "$1 $d closure link"      # read-only use; identity checked, never written
    want=$(awk -v d=$d '$1==d{print $2}' $R12/DEPS.txt); got=$(python3 -I -B $R12/tools/deps-identity.py $FG $C $d "$(realpath -e $src)" | python3 -c 'import json,sys;print(json.load(sys.stdin)["treehash"])')
    [ -n "$want" ] && [ "$got" = "$want" ] || die "$1 $d closure != DEPS.txt"; done; }
run() { (cd $OUT/$1 && timeout -k 10 300 node --test --test-reporter=tap --test-timeout=120000 $TF < /dev/null) > $OUT/logs/$1.tap 2>&1; echo $? > $OUT/logs/$1.rc; }
mk original; run original
mk patched
(cd $OUT/patched && git apply --check $ST/patches/stack-windows-chain-reader-imports.patch && git apply $ST/patches/stack-windows-chain-reader-imports.patch) || die "patch does not apply"
[ "$(sha256sum < $OUT/patched/$TF | cut -c1-64)" = 38ff63bbb76f8d982e235a370cb078ca553ac8457993d49452dbc0b4e17a6dc8 ] || die "patched test is not the reviewed bytes"
run patched
python3 -I - "$OUT/logs" <<'PY' > "$OUT/verdict.json" || rc=1
import json, re, sys, pathlib
L = pathlib.Path(sys.argv[1])
T1 = "every name the Windows chain modules import from the admission bundle is exported by the bundle AND its source entry"
EXPECTED = {"original": (1, 3, 2, 1, [T1], "importers still name chainVerifierFromEnv"), "patched": (0, 3, 3, 0, [], None)}
fails, got = [], {}
for tag, (rc, n, p, f, names, err) in EXPECTED.items():
    t = (L / f"{tag}.tap").read_text(errors="replace"); r = int((L / f"{tag}.rc").read_text())
    c = {k: int(m.group(1)) for k in ("tests", "pass", "fail", "skipped", "todo", "cancelled") for m in [re.search(rf"^# {k} (\d+)$", t, re.M)] if m}
    failing = sorted(set(re.findall(r"^not ok \d+ - (.+?)(?: #.*)?$", t, re.M))); got[tag] = {"rc": r, **c, "failing": failing}
    if (r, c.get("tests"), c.get("pass"), c.get("fail"), c.get("skipped"), c.get("todo"), c.get("cancelled"), failing) != (rc, n, p, f, 0, 0, 0, names) or (err and err not in t):
        fails.append(f"{tag}: got {got[tag]}, expected rc {rc} {n}/{p}/{f} failing {names}" + (f" with '{err}'" if err else ""))
print(json.dumps({"ok": not fails, "fails": fails, "results": got}, indent=1)); sys.exit(1 if fails else 0)
PY
(cd "$ST" && sha256sum -c --quiet SHA256SUMS) || { echo "## stage files changed during the run"; rc=1; }
cat "$OUT/verdict.json"; echo "## outputs: $OUT"; echo "## stack-import rc=$rc"; exit $rc
